inbound.set-body:
@{
            var body = context.Request.Body.As();

            var movie = new
            {
                PartitionKey = "movies",
                RowKey = Guid.NewGuid().ToString(),
                Title = (string)body["title"],
                Description = (string)body["description"],
                Year = (int)body["year"]
            };

            return JsonConvert.SerializeObject(movie);
        }

when.set-body:
@{
                    var body = context.Response.Body.As();

                    var movie = new
                    {
                        id = (string)body["RowKey"],
                        title = (string)body["Title"],
                        description = (string)body["Description"],
                        year = (int)body["Year"],
                        rating = (double?)body["Rating"]
                    };

                    return JsonConvert.SerializeObject(movie);
                }
